# frozen_string_literal: true

class ApplicationRecord < ActiveRecord::Base
  primary_abstract_class

  # Single-column uuid primary keys are generated by the application as
  # time-ordered UUIDv7 values (design specifications/08, Conventions); the
  # database default is only a fallback.
  before_create :assign_uuid_v7_primary_key

  # Text columns constrained by CHECK (... IN ...) map to string-backed enums.
  # The values must match the database; test/models/enum_consistency_test.rb
  # compares them with the live constraints.
  def self.string_enum(name, values, **options)
    enum name, values.index_with(&:itself), validate: options.delete(:validate) { true }, **options
  end

  # The attribute must name a time zone ActiveSupport knows.
  def self.validates_known_time_zone(attribute)
    validate do
      errors.add(attribute, "is not a known time zone") unless ActiveSupport::TimeZone[public_send(attribute).to_s]
    end
  end

  private

  def assign_uuid_v7_primary_key
    key = self.class.primary_key
    return unless key.is_a?(String) && self.class.columns_hash[key]&.type == :uuid
    return if self[key].present?

    self[key] = SecureRandom.uuid_v7
  end
end
